class Solution:
    def search(self, nums: list[int], target: int) -> int:
        lo, hi = 0, len(nums) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] == target:  # viz:check
                return mid  # viz:found
            if nums[lo] <= nums[mid]:  # viz:which
                if nums[lo] <= target < nums[mid]:
                    hi = mid - 1  # viz:into_left
                else:
                    lo = mid + 1  # viz:skip_left
            else:
                if nums[mid] < target <= nums[hi]:
                    lo = mid + 1  # viz:into_right
                else:
                    hi = mid - 1  # viz:skip_right
        return -1  # viz:done
